    n, d = int(data[0]), int(data[1])
    best = {}
    ans = 0
    for i in range(n):
        x = int(data[2 + i])
        v = best.get(x - d, 0) + 1
        if v > best.get(x, 0):
            best[x] = v
        if v > ans:
            ans = v
    print(ans)

