    tests.append(fmt(1, list(range(-N // 2, N // 2))))
    tests.append(fmt(7, [rng.randint(-10**9, 10**9) for _ in range(N)]))
    tests.append(fmt(1000, [(i % 3000) * 1000 - 10**6 + rng.randint(0, 1) * 1000 for i in range(N)]))
